package org.craft.mcs.cap.shared.kernel.identity;

import java.security.SecureRandom;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;
import org.jspecify.annotations.NonNull;


/**
 * Generates process-local monotonic UUID version 7 identifiers according to RFC 9562.
 *
 * <p>The 48-bit Unix timestamp provides database index locality. A 12-bit sequence preserves
 * ordering within the same millisecond and during small clock rollbacks. The remaining 62 bits
 * are generated by a cryptographically strong random source to preserve cross-process uniqueness.
 */
public final class UuidV7Generator {

  private static final long TIMESTAMP_MASK = 0x0000_FFFF_FFFF_FFFFL;
  private static final long SEQUENCE_MASK = 0xFFFL;
  private static final long VERSION_7_BITS = 0x7000L;
  private static final long RFC_9562_VARIANT_BITS = 0x8000_0000_0000_0000L;
  private static final long RANDOM_BITS_MASK = 0x3FFF_FFFF_FFFF_FFFFL;
  private static final int SEQUENCE_BITS = 12;

  private static final AtomicLong LAST_TIMESTAMP_AND_SEQUENCE = new AtomicLong();
  private static final SecureRandom RANDOM = new SecureRandom();

  private UuidV7Generator() {
  }

  /** Returns a new time-ordered UUID version 7. */
  public static @NonNull UUID newUuid() {
    final var state = nextTimestampAndSequence(System.currentTimeMillis());
    final var timestamp = state >>> SEQUENCE_BITS;
    final var sequence = state & SEQUENCE_MASK;
    final var mostSignificantBits = ((timestamp & TIMESTAMP_MASK) << 16)
        | VERSION_7_BITS
        | sequence;
    final var leastSignificantBits = (RANDOM.nextLong() & RANDOM_BITS_MASK)
        | RFC_9562_VARIANT_BITS;

    return new UUID(mostSignificantBits, leastSignificantBits);
  }

  private static long nextTimestampAndSequence(long currentTimestamp) {
    while (true) {
      final var previous = LAST_TIMESTAMP_AND_SEQUENCE.get();
      final var previousTimestamp = previous >>> SEQUENCE_BITS;
      final var previousSequence = previous & SEQUENCE_MASK;
      final var timestamp = Math.max(currentTimestamp, previousTimestamp);
      final var sequence = timestamp == previousTimestamp ? previousSequence + 1 : 0;
      final var next = sequence <= SEQUENCE_MASK
          ? (timestamp << SEQUENCE_BITS) | sequence
          : ((timestamp + 1) << SEQUENCE_BITS);

      if (LAST_TIMESTAMP_AND_SEQUENCE.compareAndSet(previous, next)) {
        return next;
      }
    }
  }
}
